ALTER TABLE public.products ADD COLUMN stock_by_variant JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.products ADD COLUMN low_stock_threshold INTEGER NOT NULL DEFAULT 5 CHECK (low_stock_threshold >= 0);
ALTER TABLE public.inventory_adjustments ADD COLUMN action TEXT NOT NULL DEFAULT 'set' CHECK (action IN ('set', 'increment', 'decrement'));
ALTER TABLE public.inventory_adjustments ADD COLUMN adjustment_amount INTEGER NOT NULL DEFAULT 0 CHECK (adjustment_amount >= 0);
ALTER TABLE public.inventory_adjustments ADD COLUMN previous_quantity INTEGER CHECK (previous_quantity IS NULL OR previous_quantity >= 0);
ALTER TABLE public.inventory_adjustments ADD COLUMN new_quantity INTEGER NOT NULL DEFAULT 0 CHECK (new_quantity >= 0);
CREATE OR REPLACE FUNCTION public.adjust_product_inventory(p_product_id UUID, p_variant_id TEXT, p_action TEXT, p_quantity INTEGER, p_reason TEXT) RETURNS TABLE(adjustment_id UUID, previous_quantity INTEGER, new_quantity INTEGER, action TEXT, adjustment_amount INTEGER, reason TEXT, created_at TIMESTAMPTZ) LANGUAGE SQL SECURITY DEFINER SET search_path = public AS $$ WITH current_product AS (SELECT p.id, p.is_demo, p.variants, p.stock_by_variant, CASE WHEN (p.stock_by_variant ->> p_variant_id) ~ '^(0|[1-9][0-9]*)$' THEN (p.stock_by_variant ->> p_variant_id)::INTEGER END AS old_count FROM public.products p WHERE p.id = p_product_id FOR UPDATE), candidate AS (SELECT c.*, CASE p_action WHEN 'set' THEN p_quantity WHEN 'increment' THEN c.old_count + p_quantity WHEN 'decrement' THEN c.old_count - p_quantity END AS new_count, (auth.uid() IS NOT NULL AND public.has_role(auth.uid(), 'admin') AND NOT c.is_demo AND p_action IN ('set','increment','decrement') AND p_quantity IS NOT NULL AND p_quantity >= CASE WHEN p_action = 'set' THEN 0 ELSE 1 END AND p_quantity <= 1000000 AND char_length(btrim(coalesce(p_reason,''))) BETWEEN 3 AND 500 AND EXISTS (SELECT 1 FROM jsonb_array_elements(c.variants) AS size(value) WHERE size.value ->> 'id' = p_variant_id) AND (p_action = 'set' OR c.old_count IS NOT NULL)) AS allowed FROM current_product c), changed AS (UPDATE public.products p SET stock_by_variant = jsonb_set(coalesce(p.stock_by_variant, '{}'::jsonb), ARRAY[p_variant_id], to_jsonb(c.new_count), true), updated_at = now() FROM candidate c WHERE p.id = c.id AND c.allowed AND c.new_count BETWEEN 0 AND 1000000 RETURNING p.id), recorded AS (INSERT INTO public.inventory_adjustments(product_id, variant_id, quantity_change, reason, changed_by, action, adjustment_amount, previous_quantity, new_quantity) SELECT c.id, p_variant_id, c.new_count - coalesce(c.old_count,0), btrim(p_reason), auth.uid(), p_action, p_quantity, c.old_count, c.new_count FROM candidate c JOIN changed d ON d.id = c.id RETURNING id, public.inventory_adjustments.previous_quantity, public.inventory_adjustments.new_quantity, public.inventory_adjustments.action, public.inventory_adjustments.adjustment_amount, public.inventory_adjustments.reason, public.inventory_adjustments.created_at) SELECT id, previous_quantity, new_quantity, action, adjustment_amount, reason, created_at FROM recorded $$;
REVOKE ALL ON FUNCTION public.adjust_product_inventory(UUID,TEXT,TEXT,INTEGER,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.adjust_product_inventory(UUID,TEXT,TEXT,INTEGER,TEXT) TO authenticated;